"""Assemble an offline, self-contained review page from actual browser captures."""
from pathlib import Path
import base64
import json

ROOT = Path(__file__).resolve().parent
directions = [
    ('a-lab-manual', 'A', '实验手册', '轮盘 #10 · Bauhaus Geometric', '用鲜明的课程主区与编号工具列，给第一次进入的学员一个明确起点。', '「读、跑、看」形成相邻的操作板块。'),
    ('b-tool-workspace', 'B', '工具工作台', '现实参照 · IBM Carbon', '持久侧栏保留位置感，把课程、身份与实验工具收进紧凑的工作台。', '同一账号的环境与工具，形成可反复切换的工作区。'),
    ('c-reading-first', 'C', '阅读优先', '设计师思考锚点 · Information Architects', '温和纸色与阅读排版，直接进入第一课；下方工具横栏保留实验入口。', '首课阅读区与下方工具横栏，来自先理解、再动手的顺序。'),
]
shots = {}
cards = []
for slug, letter, title, anchor, desc, form in directions:
    shots[slug] = {}
    for view in ['workspace', 'activity', 'lesson']:
        p = ROOT / f'screenshots/{slug}-{view}-1440.png'
        shots[slug][view] = 'data:image/png;base64,' + base64.b64encode(p.read_bytes()).decode()
    cards.append(f'''<article><div class="card-top"><span class="letter">{letter}</span><div><h2>{title}</h2><p class="anchor">{anchor}</p></div></div><a class="shot" href="design-demos/{slug}.html" aria-label="打开{letter}版完整原型"><img data-slug="{slug}" src="{shots[slug]['workspace']}" alt="{title}个人首页真实浏览器截图"></a><p class="desc">{desc}</p><p class="form">构图来源：{form}</p><div class="links"><a href="design-demos/{slug}.html">打开交互初稿 ↗</a><a href="screenshots/{slug}-workspace-1440.png">原尺寸截图 ↗</a></div></article>''')

html = '''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none';img-src data:;style-src 'unsafe-inline';script-src 'unsafe-inline';connect-src 'none';base-uri 'none';form-action 'none'"><title>AWS-27.1 · 三方向页面初稿</title><style>
*{box-sizing:border-box}body{margin:0;color:#1d2434;background:#f4f6f3;font:15px/1.7 'PingFang SC','Microsoft Yahei',sans-serif}main{max-width:1600px;margin:auto;padding:40px 38px}header{display:flex;justify-content:space-between;gap:40px;align-items:flex-start;margin-bottom:28px}.eyebrow{font-size:12px;font-weight:700;letter-spacing:1px;color:#486054;margin-bottom:8px}h1{font-size:32px;letter-spacing:-1px;margin:0 0 12px}header p{font-size:14px;color:#526257;margin:0;max-width:76ch}.status{font-size:12px;white-space:nowrap;border:1px solid #becdc0;padding:7px 13px;border-radius:30px;color:#345744}nav{display:flex;align-items:center;gap:10px;border-top:1px solid #ccd6ca;padding:20px 0;margin-bottom:10px}nav span{font-size:13px;margin-right:10px;color:#526257}button{border:1px solid #b9c9bd;border-radius:4px;background:transparent;color:#1d2434;padding:9px 18px;font:inherit;font-size:13px;cursor:pointer}button[aria-pressed=true]{background:#1d2434;color:white;border-color:#1d2434}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:23px}article{min-width:0;background:#fff;border:1px solid #cad5cd}.card-top{display:flex;align-items:center;gap:16px;padding:20px}.letter{font-size:28px;font-weight:650}.card-top h2{font-size:19px;margin:0}.anchor{font-size:12px;color:#56675c;margin:3px 0 0}.shot{display:block;margin:0 14px;border:1px solid #d4ddd7;height:330px;overflow:auto;background:#f8f9f6}.shot img{width:100%;height:auto;display:block}.desc{font-size:14px;margin:20px 20px 10px;min-height:50px;color:#314539}.form{font-size:12px;color:#526257;margin:0 20px;min-height:44px}.links{display:flex;justify-content:space-between;gap:10px;margin:18px 20px 21px;font-size:13px}.links a{color:#046c4f;text-decoration:none;border-bottom:1px solid #b9ccbe}footer{display:flex;gap:25px;justify-content:space-between;border-top:1px solid #cad5cd;padding-top:18px;margin-top:28px;font-size:13px;color:#526257}footer p{margin:0;max-width:70ch}a:focus-visible,button:focus-visible{outline:3px solid #047957;outline-offset:4px}@media(min-width:1500px){.shot{height:380px}}@media(max-width:900px){main{padding:28px 20px}header{display:block}.status{display:inline-block;margin-top:18px}.grid{grid-template-columns:1fr}.shot{height:auto;max-height:540px}.desc,.form{min-height:0}.links{justify-content:flex-start;gap:30px}h1{font-size:27px}footer{display:block}footer p+p{margin-top:12px}nav{flex-wrap:wrap}}
</style></head><body><main><header><div><div class="eyebrow">AWS-27.1 / DESIGN EXPLORATIONS / 2026.11.04</div><h1>同一条学习路径，三种组织方式。</h1><p>选择活动 → 托管登录 → 本人环境 → 阅读与实验。三版共用英文课程、官方标识与同一组示例数据；可打开完整原型切换页面与异常状态。</p></div><span class="status">方向待选择 · 页面尚未实施</span></header><nav aria-label="对比页面"><span>比较同一页面</span><button data-screen="workspace" aria-pressed="true">个人首页</button><button data-screen="activity" aria-pressed="false">活动入口</button><button data-screen="lesson" aria-pressed="false">课程阅读</button></nav><section class="grid">__CARDS__</section><footer><p>每版包含登录、首登改密、MFA、课程目录、阅读、终端引导及异常/退出状态。托管登录仅示意允许调整的品牌样式，字段与文案以实际认证页面为准。</p><p>本轮仅作本地设计评审。所有身份与状态均为示例，未连接真实服务。</p></footer></main><script>const shots=__SHOTS__;document.querySelectorAll('[data-screen]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-screen]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('[data-slug]').forEach(img=>{img.src=shots[img.dataset.slug][b.dataset.screen];img.alt=img.dataset.slug+' '+b.textContent+' 真实截图'});document.querySelectorAll('.shot').forEach(x=>x.scrollTop=0)}));</script></body></html>'''.replace('__CARDS__', ''.join(cards)).replace('__SHOTS__', json.dumps(shots))
(ROOT/'index.html').write_text(html)
print('Gallery ready:', len(html), 'bytes')
